const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = n => `<svg class="icon" aria-hidden="true"><use href="#i-${n}"/></svg>`;
const key = 'relay-prototype-v1';
const fresh = () => ({version:1,view:'desk',tab:'pending',selected:1,role:'senior',context:'profile',accepted:false,closed:false,chatOpen:false,apiFail:false,feedback:null,summaryError:false,query:'',draft:'',draftIndex:0,tickets:[],afterSale:null,transferred:true,transferReason:'客户投诉 · 超出 AI 授权范围',core:'收到的保温杯杯盖破损，要求退货退款，并投诉退货运费问题。',events:['意图识别：售后 / 商品破损','订单与知识库检索完成','检测到投诉，转入高级客服队列','结构化摘要与历史记录已同步'],messages:[{role:'user',text:'刚收到的保温杯杯盖是坏的，我要退货。'},{role:'ai',text:'很抱歉给您带来不好的体验。已为您找到这笔订单，商品在售后期内，可以为您申请退货退款。',card:'order'},{role:'ai',text:'商品质量问题支持退货退款，退货运费由商家承担。您可以确认下方方案，我来帮您发起申请。',card:'scheme'},{role:'user',text:'上次客服说运费要我自己出，你们到底什么规定？我要投诉，找人工处理！'},{role:'system',text:'已识别投诉诉求，正在为您转接高级客服。历史记录与处理进度将同步。'}]});
let state;
try { state = JSON.parse(localStorage.getItem(key)); } catch {}
if (!state || state.version !== 1) state=fresh();
state.query=''; state.draft=state.draft||'';
let toastTimer, previousFocus;
function persist(){try{localStorage.setItem(key,JSON.stringify(state));}catch{}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3300)}
const names={desk:'会话工作台',customer:'C 端体验',knowledge:'知识库',tickets:'售后工单',overview:'数据概览',rules:'集成与规则'};
const articles=[{id:1,title:'商品质量问题退货政策',category:'售后政策',version:'KB-2026-018 · v2.3',body:'商品存在破损、功能异常等质量问题，可在签收后 7 日内提交退货退款申请。经售后审核确认后，退货运费由商家承担。退款将在商品退回并验收后原路退还。',scope:'适用于本演示订单的质量问题售后，不等同于全部商品通用条款。'},{id:2,title:'退款进度与到账说明',category:'资金说明',version:'KB-2026-021 · v1.8',body:'售后申请创建后，先等待审核与退货。退回商品验收通过后发起退款，演示到账时效为 1–3 个工作日。用户可通过工单查看当前处理阶段。',scope:'涉及退款执行及金额变更时，需要人工审批和资金系统确认。'},{id:3,title:'投诉升级与人工接入指引',category:'服务规范',version:'KB-2026-032 · v1.2',body:'用户明确投诉、涉及高风险事项或 AI 无法可靠回答时，转入人工队列。高级客服优先处理高风险会话。接入时先确认已阅读历史记录，再说明下一步动作。',scope:'转交字段：核心诉求、已执行动作、当前状态、转人工原因。'}];
const otherSessions=[{id:2,name:'陈予安',initial:'陈',tone:'purple',risk:1,wait:8,status:'pending',reason:'物流延迟',preview:'物流三天没有更新，可以帮我催一下吗？',order:'RL202610190126',amount:'169.00'},{id:3,name:'周言',initial:'周',tone:'blue',risk:0,wait:3,status:'ai',reason:'发票咨询',preview:'好的，我找到了电子发票，谢谢。',order:'RL202610180352',amount:'89.00'},{id:4,name:'许知夏',initial:'许',tone:'',risk:0,wait:1,status:'active',reason:'商品咨询',preview:'这款保温杯可以放洗碗机清洗吗？',order:'RL202610200917',amount:'129.00'}];
function sessions(){const high=state.transferred&&/投诉|高风险/.test(state.transferReason);return [{id:1,name:'林晓',initial:'林',tone:'',risk:high?2:0,wait:12,status:state.closed?'done':state.accepted?'active':state.transferred?'pending':'ai',reason:high?'商品破损 · 投诉':'商品破损 · 售后',preview:state.messages.filter(m=>m.role!=='system').at(-1)?.text||'售后咨询',order:'RL202610220831',amount:'129.00'},...otherSessions];}
function selected(){return sessions().find(x=>x.id===state.selected)||sessions()[0];}
function navButton(view,ico){return `<button aria-label="${names[view]}" title="${names[view]}" class="${state.view===view?'active':''}" data-action="nav" data-view="${view}" ${state.view===view?'aria-current="page"':''}>${icon(ico)}<span>${names[view]}</span>${view==='desk'?`<span class="count">${sessions().filter(s=>s.status==='pending').length}</span>`:''}</button>`;}
function render(){
  $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">${icon('chat')}</div><div><b>同频</b><em>R E L A Y</em></div></div><div class="nav-label">工作空间 / WORKSPACE</div><nav class="nav" aria-label="主导航">${navButton('desk','chat')}${navButton('customer','phone')}${navButton('knowledge','book')}${navButton('tickets','file')}${navButton('overview','up')}</nav><div class="nav-divider"></div><div class="nav-label">管理 / MANAGE</div><nav class="nav">${navButton('rules','grid')}</nav><div class="sidebar-bottom"><div class="side-note"><strong>${icon('shield')} 安全协同，始终在线</strong>敏感信息默认脱敏<br>每一次交接都有迹可循</div><button class="ghost small" data-action="guide">${icon('help')} 原型说明与演示指南</button><div class="profile"><div class="avatar me">叶</div><div><b>叶青 <span class="dot"></span></b><small>${state.role==='senior'?'高级客服':'普通客服'} · 售后服务组</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">工作空间 <span style="margin:0 9px;color:#d6dadd">/</span><b>${names[state.view]}</b></div><div class="top-actions flex"><span class="mode-label">交互原型 · 全部为模拟数据</span><button class="ghost small" data-action="guide">${icon('help')} 演示指南</button><button class="ghost small" data-action="reset">${icon('refresh')} 重置</button></div></header><div class="content">${renderView()}</div></main></div>`;
  persist();
}
function renderView(){return ({desk:renderDesk,customer:renderCustomer,knowledge:renderKnowledge,tickets:renderTickets,overview:renderOverview,rules:renderRules}[state.view]||renderDesk)();}
function heading(title,desc,actions=''){return `<div class="page-heading between"><div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`;}
function metric(label,value,unit,foot,ico){return `<div class="metric"><div class="metric-title">${label}${icon(ico)}</div><div class="metric-value">${value}<small>${unit}</small></div><div class="metric-foot">${foot}</div></div>`;}
function renderDesk(){const ss=sessions();return `${heading('会话工作台','让 AI 处理重复，让人工专注每一次重要对话。',`<select id="role-select" aria-label="客服角色"><option value="senior" ${state.role==='senior'?'selected':''}>高级客服 · 叶青</option><option value="normal" ${state.role==='normal'?'selected':''}>普通客服 · 叶青</option></select><button class="primary small" data-action="nav" data-view="customer">${icon('phone')} 体验客户端</button>`)}<div class="metric-grid">${metric('等待接入',ss.filter(s=>s.status==='pending').length,'个会话','<span>优先关注</span> '+ss.filter(s=>s.status==='pending'&&s.risk===2).length+' 个高风险投诉','clock')}${metric('人工服务中',ss.filter(s=>s.status==='active').length,'个会话','<span>上下文已同步</span> 无需重复询问','user')}${metric('AI 服务中',ss.filter(s=>s.status==='ai').length,'个会话','<span>自动处理</span> 标准咨询与售后','spark')}${metric('已创建售后',state.tickets.length,'个工单','<span>演示记录</span> 可在工单页查看','file')}</div><div class="desk ${state.chatOpen?'chat-open':''}"><section class="queue"><div class="panel-head"><div class="between"><h2>会话队列 <span class="muted">${ss.length}</span></h2><span class="tag green"><span class="dot"></span> 在线</span></div><div class="search">${icon('search')}<input id="queue-search" type="search" placeholder="搜索客户、订单或问题" aria-label="搜索会话" value="${esc(state.query)}"></div></div><div class="tabs" role="tablist" aria-label="会话状态">${[['pending','待接入'],['active','服务中'],['ai','AI 处理中'],['done','已结束']].map(([v,l])=>`<button role="tab" aria-selected="${state.tab===v}" class="${state.tab===v?'active':''}" data-action="tab" data-tab="${v}">${l} ${ss.filter(s=>s.status===v).length}</button>`).join('')}</div><div class="route-hint">${icon('shield')} 按风险等级 → 等待时长排序</div><div id="queue-items">${renderQueue()}</div><div class="queue-footer">${icon('shield')} 高风险会话仅限高级客服接入</div></section>${renderConversation()}${renderContext()}</div><div class="footer-line"><span><span class="dot"></span> 演示模式 · 数据仅保存在当前浏览器</span><span>知识库 / 订单 / 工单 · 三系统联动演示</span></div>`;}
function renderQueue(){const ss=sessions().filter(s=>s.status===state.tab && `${s.name}${s.order}${s.reason}${s.preview}`.toLowerCase().includes(state.query.toLowerCase())).sort((a,b)=>b.risk-a.risk||b.wait-a.wait);return ss.length?ss.map(s=>`<button class="session ${state.selected===s.id?'active':''}" data-action="session" data-id="${s.id}"><div class="between"><div class="flex"><span class="avatar ${s.tone}">${s.initial}</span><h3>${s.name}</h3></div><time>${s.status==='pending'?`等待 ${s.wait} 分钟`:'刚刚'}</time></div><p class="preview">${esc(s.preview)}</p><div class="labels"><span class="tag ${s.risk===2?'red':s.risk===1?'orange':''}">${s.risk===2?'高风险投诉':s.risk===1?'等待较久':'普通咨询'}</span><span class="tag">${s.reason}</span></div></button>`).join(''):`<div class="queue-empty">${state.query?'没有匹配的会话':'当前队列已清空'}<br><small>${state.query?'试试客户姓名或订单号':'切换其他队列查看会话'}</small></div>`;}
function summary(){return `<div class="summary"><div class="summary-head"><span class="flex">${icon('spark')} AI 处理摘要</span><span class="tag green">上下文已同步</span></div><dl class="summary-grid"><dt>核心诉求</dt><dd>${esc(state.core)}</dd><dt>已执行动作</dt><dd>${state.afterSale?`已创建售后申请 ${esc(state.afterSale)}，尚未执行退款。`:'已检索订单及售后政策，展示退货退款方案；未提交申请，未执行退款。'}</dd><dt>当前状态</dt><dd>${state.closed?'人工处理已结束':state.accepted?'人工已接入，处理中':'等待人工接入'}${state.afterSale?' · 售后待审核':''}</dd><dt>转人工原因</dt><dd>${esc(state.transferReason)}</dd></dl><div class="summary-footer"><span>基于当前完整对话生成 · 规则模拟</span><button data-action="summary-error">${state.summaryError?'已反馈 · 待核查':'⚑ 标记摘要有误'}</button></div></div>`;}
function renderConversation(){const s=selected(),isMain=s.id===1;const canReply=isMain&&state.accepted&&!state.closed;
 const actions=isMain?(state.closed?'<span class="tag">会话已结束</span>':!state.transferred?'<span class="tag green">AI 处理中</span>':state.accepted?'<button class="small" data-action="close-session">完成会话</button>':`<button class="primary" data-action="accept">${icon('user')} 接入会话</button>`):'<span class="tag">示例会话 · 只读</span>';
 return `<section class="conversation"><div class="conv-head between"><div class="flex"><button class="ghost mobile-back" data-action="queue-back" aria-label="返回会话队列">‹</button><div><div class="flex"><h2>${s.name}</h2><span class="tag ${s.risk===2?'red':'orange'}">${s.risk===2?'高风险':'普通'}</span></div><small>会话 #CS-20261024-00${s.id} · ${isMain?'售后退款 / 商品破损':s.reason}</small></div></div>${actions}</div><div class="conv-scroll" id="staff-scroll">${isMain&&state.transferred?summary():`<div class="info-banner">${isMain?'AI 正在处理，转人工时会自动同步结构化摘要。':'这是队列与路由展示会话。完整联动请体验「林晓」的售后场景。'}</div>`}<div class="time-divider">今天 · 演示会话</div>${isMain?state.messages.map(m=>renderMessage(m,false)).join(''):renderMessage({role:'user',text:s.preview},false)}</div><div class="composer">${isMain?`<div class="copilot"><div class="copilot-title between"><span class="flex">${icon('spark')} AI Copilot · 回复建议</span><span class="tag green">规则生成示例</span></div><div class="copilot-draft">${esc(draftText())}</div><div class="copilot-actions"><button data-action="regenerate" ${canReply?'':'disabled'}>${icon('refresh')} 重新生成</button><button class="primary" data-action="adopt" ${canReply?'':'disabled'}>采用并编辑</button></div></div><form id="staff-form"><div class="input-area"><textarea id="staff-input" aria-label="客服回复" placeholder="${canReply?'输入回复，或采用 AI 建议后编辑…':'接入会话后，可编辑并发送回复'}" ${canReply?'':'disabled'}>${esc(state.draft)}</textarea></div><div class="compose-bottom"><small>${canReply?'Enter 换行 · Ctrl / ⌘ + Enter 发送':'请先接入会话 · 历史记录已保留'}</small><button class="primary" type="submit" ${canReply?'':'disabled'}>发送 ${icon('send')}</button></div></form>`:'<p class="muted" style="font-size:11px;padding:16px">选择林晓的会话，体验完整的人机协同流程。</p>'}</div></section>`;
}
function draftText(){if(state.afterSale)return state.draftIndex%2===0?`林女士，您的售后申请 ${state.afterSale} 已提交，目前待审核，退款尚未执行。退货运费由商家承担，我会继续跟进审核进度，并及时告知您下一步安排。`:`已为您核实，售后工单 ${state.afterSale} 处于待审核阶段。请先等待审核与退货安排，商品退回并验收后才会发起退款。您的问题我会持续跟进。`;return (state.draftIndex%2===0?'林女士您好，我已看到历史记录，了解到杯盖破损及您对退货运费的担忧，无需再次描述。质量问题的退货运费由商家承担。我会为您提交退货退款申请，审核后同步处理进度。':'林女士您好，您的历史沟通和商品破损情况我已经了解。很抱歉给您带来困扰。本次质量问题售后由商家承担退货运费，我将协助发起申请，并持续跟进审核及退款进度。');}
function renderMessage(m,client){
 if(m.role==='system')return `<div class="system-note">${esc(m.text)}</div>`;
 const staff=m.role==='staff'||(client&&m.role==='user'),ai=m.role==='ai';
 return `<div class="message ${staff?'staff':''}"><div class="avatar ${ai?'ai':m.role==='staff'?'me':''}">${ai?icon('spark'):m.role==='staff'?'叶':'林'}</div><div class="message-body"><div class="message-name">${ai?'同频 AI 助手':m.role==='staff'?'叶青 · 人工客服':'林晓'}${ai?' · AI 生成示例':''}</div><div class="bubble">${esc(m.text)}</div>${m.card==='order'&&client?orderCard(true):''}${m.card==='scheme'&&client?schemeCard():''}${m.card==='error'&&client?`<div class="phone-message-card"><h3>订单服务暂时不可用</h3><p>未提交任何售后申请。可恢复接口后重试，或携带当前上下文转人工。</p><button data-action="retry-api">恢复接口并重试</button><button data-action="handoff" data-reason="订单接口异常 · 人工核查">转人工处理</button></div>`:''}${ai&&m.card==='scheme'?`<button class="source-link" data-action="article" data-id="1">${icon('book')} 引用：商品质量问题退货政策 ↗</button>${client?`<div class="feedback">这个回答有帮助吗？<button data-action="feedback" data-value="up" class="${state.feedback==='up'?'selected':''}" aria-pressed="${state.feedback==='up'}">有帮助</button><button data-action="feedback" data-value="down" class="${state.feedback==='down'?'selected':''}" aria-pressed="${state.feedback==='down'}">没帮助</button></div>`:''}`:''}</div></div>`;
}
function orderCard(client=false){const s=client?sessions()[0]:selected();return `<div class="order-card"><div class="between order-number"><span>订单 ${s.order}</span><span class="tag green">${s.id===2?'运输中':'已签收'}</span></div><div class="product"><div class="product-art" aria-label="保温杯示意图"><div class="cup"></div></div><div><h4>轻行 · 真空保温杯</h4><p>苔原绿 / 480mL × 1</p><strong>¥ ${s.amount}</strong></div></div><dl class="keyval"><dt>下单时间</dt><dd>2026-10-22 14:32</dd><dt>售后状态</dt><dd>${state.afterSale&&s.id===1?'<span class="green">申请已提交 · 待审核</span>':'未发起 · 售后有效期内'}</dd></dl><div class="logistics"><span class="dot"></span>顺丰速运 · 10 月 24 日已签收</div><button class="${client?'primary':''}" data-action="${client?'sale-plan':'ticket-form'}" ${state.afterSale&&s.id===1?'disabled':''}>${icon(client?'refresh':'file')}${state.afterSale&&s.id===1?'售后申请已提交':client?'申请退货退款':'创建售后工单'}</button></div>`;}
function schemeCard(){return `<div class="phone-message-card"><div class="between"><h3>推荐售后方案</h3><span class="tag green">符合申请条件</span></div><dl class="keyval"><dt>处理方式</dt><dd>退货退款</dd><dt>申请金额</dt><dd>¥ 129.00</dd><dt>退货运费</dt><dd>商家承担</dd></dl><p>最终以审核结果为准，提交申请不会立即退款。</p><button class="primary" data-action="sale-plan" ${state.afterSale?'disabled':''}>${state.afterSale?'已提交申请':'查看方案并确认'}</button></div>`;}
function renderContext(){const s=selected();return `<aside class="context"><div class="tabs context-tabs"><button data-action="context" data-value="profile" class="${state.context==='profile'?'active':''}">客户全景</button><button data-action="context" data-value="history" class="${state.context==='history'?'active':''}">历史会话</button></div>${state.context==='history'?`<div class="context-section" style="grid-column:1/-1"><h3>${icon('clock')} 历史服务记录</h3><div class="knowledge-snippet"><b>10 月 20 日 · 商品咨询</b><p>咨询杯体材质与容量。AI 提供商品说明，客户确认已解决。</p><button data-action="history-detail">查看完整记录 →</button></div><div class="info-banner">当前会话的完整历史始终保留在中间对话区。</div></div>`:`<section class="context-section"><h3>${icon('user')} 客户信息 <span class="tag">已脱敏</span></h3><div class="customer-profile"><div class="avatar ${s.tone}">${s.initial}</div><b>${s.name}</b> <span class="tag orange">PLUS 会员</span><div class="labels"><span class="tag">老客户</span><span class="tag">关注服务体验</span></div></div><dl class="keyval"><dt>手机号码</dt><dd>138 **** 6028</dd><dt>所在地区</dt><dd>浙江省 · 杭州市</dd><dt>累计消费</dt><dd>¥ 2,386.00</dd><dt>历史订单</dt><dd>12 笔</dd></dl></section><section class="context-section"><h3>${icon('box')} 相关订单 <span class="tag">1</span></h3>${s.id===1?orderCard():`<div class="knowledge-snippet"><b>${s.order}</b><p>¥ ${s.amount} · ${s.id===2?'物流运输中':'订单已完成'}</p><p>该会话为只读示例。</p></div>`}</section><section class="context-section"><h3>${icon('book')} 相关知识</h3><div class="knowledge-snippet"><b style="font-size:11px">商品质量问题退货政策</b><p>签收 7 日内可申请，质量问题运费由商家承担。</p><button data-action="article" data-id="1">查看引用原文 →</button></div></section>`}</aside>`;}
function renderCustomer(){return `${heading('C 端 Agent 体验','同一段对话，在 AI 与人工之间自然接续。',`<select id="api-select" class="customer-select" aria-label="模拟接口状态"><option value="normal" ${!state.apiFail?'selected':''}>订单接口：正常</option><option value="fail" ${state.apiFail?'selected':''}>模拟接口异常</option></select><button class="small" data-action="new-scenario">从 AI 售后开始</button><button class="primary small" data-action="open-staff">切换客服端 ${icon('arrow')}</button>`)}<div class="customer-layout"><section class="experience-intro"><div class="section-kicker">CONNECTED BY CONTEXT</div><h2 class="view-title">每个问题，<br>都有人接得住。</h2><p>AI 看懂问题、找到订单、给出方案。需要人工时，带着完整上下文继续对话。</p>${[['01','卡片即服务','订单、方案与引用来源，一眼看清。'],['02','交接不失忆','诉求、动作、状态、原因，同步到人工端。'],['03','执行有边界','售后需确认，异常能重试，资金需审核。']].map(([n,t,d])=>`<div class="flow-step"><span>${n}</span><div><b>${t}</b><p>${d}</p></div></div>`).join('')}<button class="ghost small green" style="margin-top:22px" data-action="components">查看 21 个核心交互组件 ${icon('arrow')}</button></section><section class="phone" aria-label="客户手机端演示"><div class="phone-status"><span>9:41</span><span>◔ ▰</span></div><div class="phone-header"><div class="avatar ai">${icon(state.accepted?'user':'spark')}</div><div><h2>同频服务助手</h2><p><span class="dot"></span> ${state.closed?'会话已结束 · 感谢您的信任':state.accepted?'叶青 · 高级客服正在为您服务':state.transferred?'已转人工 · 等待客服接入':'AI 在线 · 为您提供贴心服务'}</p></div><button class="ghost small" style="margin-left:auto" data-action="handoff" data-reason="用户主动要求人工服务" ${state.transferred||state.closed?'disabled':''}>转人工</button></div><div class="phone-chat" id="customer-scroll"><div style="font-size:9px;text-align:center;color:#a5b0a7">官方客服 · 服务记录全程保留</div>${state.messages.map(m=>renderMessage(m,true)).join('')}</div><div class="phone-bottom"><div class="quick-actions"><button data-action="quick" data-text="查询我的订单">${icon('box')} 查订单</button><button data-action="quick" data-text="我要退货退款">退货退款</button><button data-action="quick" data-text="退款什么时候到账？">退款进度</button><button data-action="quick" data-text="我要投诉，请转人工">投诉 / 转人工</button></div><form class="phone-input" id="customer-form"><input id="customer-input" aria-label="客户消息" placeholder="请描述您的问题…" autocomplete="off" ${state.closed?'disabled':''}><button class="primary" type="submit" aria-label="发送客户消息" ${state.closed?'disabled':''}>${icon('send')}</button></form><div class="phone-safe">AI 生成内容仅供参考 · 演示不产生真实售后或退款</div></div></section><aside class="event-panel"><div class="section-kicker">AGENT ACTIVITY</div><h3>服务流转轨迹</h3><p>关键动作与执行边界<br>在两个端保持同步。</p><div class="event-list">${state.events.map((e,i)=>`<div class="event">${esc(e)}<small>STEP ${String(i+1).padStart(2,'0')} · ${i===state.events.length-1?'当前进度':'已完成'}</small></div>`).join('')}</div><div class="info-banner">${state.apiFail?'当前模拟：订单接口异常。点击「查订单」体验重试与转人工兜底。':'此处使用规则模拟 Agent，不调用真实模型或业务 API。'}</div></aside></div>`;}
function renderKnowledge(){return `${heading('知识库','让每一次回答有据可查，每一条政策可追溯。',`<span class="tag green">3 篇演示文档 · 已生效</span>`)}<div class="info-banner">引用卡片可查看文档编号、版本及适用范围。人工端可将政策内容插入回复草稿。</div><div class="library-grid">${articles.map(a=>`<article class="card"><span class="tag green">${a.category}</span><h3>${a.title}</h3><p>${a.body}</p><div class="version">${a.version}</div><button class="small" style="margin-top:15px" data-action="article" data-id="${a.id}">查看原文与引用 ${icon('arrow')}</button></article>`).join('')}</div>`;}
function renderTickets(){return `${heading('售后工单','客户、订单与会话记录，始终关联在一起。',`<button class="primary small" data-action="ticket-form">${icon('file')} 新建售后工单</button>`)}<div class="info-banner">模拟售后流程：提交申请 → 待审核。原型不会执行真实退款，同一订单的重复提交将复用已有工单。</div>${state.tickets.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>工单编号</th><th>关联客户 / 订单</th><th>售后类型</th><th>申请金额</th><th>处理状态</th><th>操作</th></tr></thead><tbody>${state.tickets.map(t=>`<tr><td>${esc(t.id)}</td><td>林晓<br><small class="muted">RL202610220831</small></td><td>退货退款</td><td>¥ 129.00</td><td><span class="tag orange">待审核</span></td><td><button data-action="ticket-detail" data-id="${t.id}">查看详情</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="card empty-state">${icon('file')}<h2>还没有售后工单</h2><p>从 C 端确认售后方案，或在工作台创建售后，工单将显示在这里。</p><button class="small" style="margin-top:20px" data-action="nav" data-view="desk">前往工作台 ${icon('arrow')}</button></div>`}`;}
function renderOverview(){return `${heading('项目成效概览','以下数值来自需求描述，用于呈现项目目标与价值。',`<span class="tag orange">参考成效 · 非原型实测</span>`)}<div class="overview-numbers">${[['AI 独立解决率','65%','整体咨询由 AI 独立解决',65],['人工平均处理时长','↓ 40%','AHT 相对项目实施前缩短',40],['客户重复描述率','85% → 5%','转人工后重复描述问题的比例',94],['售后 AI 独立闭环率','70%','售后场景由 AI 完成闭环',70],['系统切换次数','4 → 0','单次会话跨系统切换次数',100],['回复草稿采纳率','60%','人工客服采用 AI 建议的比例',60]].map(([t,v,d,w])=>`<article class="card"><h3>${t}</h3><b>${v}</b><p>${d}</p><div class="outcome-bar"><i style="width:${w}%"></i></div><small class="muted">项目材料参考值</small></article>`).join('')}</div><div class="info-banner">统计口径提示：「上下文断层客诉为 0」与「客户重复描述率为 5%」是不同指标。真实上线需分别定义样本、周期、分母和埋点；本原型不验证这些业务成效。</div>`;}
function renderRules(){return `${heading('集成与规则','明确交互背后的数据契约、执行边界与失败路径。',`<button class="small" data-action="components">${icon('grid')} 21 个交互组件</button>`)}<div class="info-banner">这是产品接口契约草案，所有调用由浏览器模拟。生产环境需由后端完成鉴权、权限校验、幂等、审计及模型调用。</div><div class="integration-grid"><article class="card"><h2>三系统 API 联动</h2>${[['GET /api/orders?customer_id=…','订单系统','返回 order_id / items / amount / delivery / after_sale_status；仅返回授权客户的订单。'],['POST /api/knowledge/search','知识库系统','输入 query / conversation_id；返回 answer / citations（doc_id、version、section）。'],['POST /api/after-sales','工单系统','输入 order_id / reason / amount / consent；请求头传 Idempotency-Key，创建后返回 ticket_id / status。'],['POST /api/conversations/:id/handoff','会话系统','提交 summary 四字段及完整 transcript 引用；原子更新状态，转交成功后停止 AI 自动回复。']].map(([path,title,d])=>`<div class="api-line"><span class="tag green">${title}</span><p><code>${esc(path)}</code></p><p>${d}</p></div>`).join('')}<button style="margin-top:17px" class="small" data-action="api-contract">查看转交数据示例 ${icon('arrow')}</button></article><article class="card"><h2>路由、权限与异常兜底</h2>${[['优先级与分配','先按风险等级降序，再按等待时长降序。高风险投诉只允许高级客服接入。可在工作台切换角色验证。'],['人工接管','触发投诉、AI 拒答、用户主动要求或接口异常，携带摘要与完整历史转人工。人工接入后 AI 停止自动发送。'],['执行与确认','创建售后前展示金额、原因及规则，用户确认后才提交；人工创建需要客户授权。退款执行另行审核。'],['接口失败','订单查询异常时不推断订单状态、不执行售后；提供重试和转人工。可在 C 端选择「模拟接口异常」验证。'],['超时与模型边界','C 端输入「超时」可触发模型超时兜底，输入「人工」可主动转接；规则外问题按无法可靠回答转人工。'],['脱敏与反馈','电话默认脱敏。点赞/点踩、摘要纠错在浏览器保存；生产环境需按角色限制字段并记录审计事件。']].map(([t,d])=>`<div class="rule-row"><strong>${t}</strong><p>${d}</p></div>`).join('')}</article></div>`;}
function modal(title,body,footer='',wide=false){previousFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header><h2 id="modal-title">${title}</h2><button class="close" data-action="modal-close" aria-label="关闭弹窗">×</button></header>${body}${footer?`<footer>${footer}</footer>`:''}</section></div>`;$('.modal .close').focus();}
function closeModal(){ $('#modal-root').innerHTML='';if(previousFocus?.isConnected)previousFocus.focus();}
function scrollMessages(){requestAnimationFrame(()=>{for(const id of ['customer-scroll','staff-scroll']){const el=document.getElementById(id);if(el)el.scrollTop=el.scrollHeight;}});}
function addEvent(t){state.events.push(t);if(state.events.length>9)state.events.shift();}
function handoff(reason){if(state.closed){toast('会话已结束，请重置演示或开始新的售后场景');return;}if(state.transferred){toast(state.accepted?'人工客服已接入，请直接继续沟通':'已在人工队列中，历史记录与摘要已同步');return;}state.transferred=true;state.transferReason=reason;state.tab='pending';state.selected=1;state.core=reason.includes('投诉')?'商品破损售后，客户对运费政策提出投诉，要求人工处理。':reason.includes('异常')?'订单服务异常，客户希望继续核查订单并处理售后。':'客户咨询售后问题，希望人工继续处理；请结合完整历史核实诉求。';state.messages.push({role:'system',text:`正在转接人工客服（${reason}）。已同步历史记录，您无需再次描述。`});addEvent('触发人工路由：'+reason);addEvent('四字段摘要与完整对话已同步');persist();render();scrollMessages();toast('已转人工，可切换客服端查看完整上下文');}
function customerSend(text){text=text.trim();if(!text)return;if(state.closed){toast('当前会话已结束，请开始新的演示场景');return;}state.messages.push({role:'user',text});if(state.transferred){addEvent(state.accepted?'客户新消息已同步给人工客服':'排队期间新消息已补充至会话历史');render();scrollMessages();toast('消息已同步到人工工作台');return;}
 if(/投诉|人工|举报|赔偿|起诉/.test(text)){handoff(/投诉|举报|赔偿|起诉/.test(text)?'高风险投诉 · 超出 AI 授权范围':'用户主动要求人工服务');return;}
 if(/超时/.test(text)){state.messages.push({role:'ai',text:'本次响应等待超时，尚未执行任何业务操作。我将为您转接人工继续处理。'});handoff('AI 响应超时 · 自动兜底');return;}
 if(/订单|物流|退货|退款|售后|坏|破损/.test(text)){
 if(state.apiFail){state.messages.push({role:'ai',text:'订单服务暂时不可用，我无法确认订单状态。您的消息已保留，请重试或转人工。',card:'error'});addEvent('订单 API 异常：未执行业务操作');}
 else if(/到账|进度/.test(text)){state.messages.push({role:'ai',text:state.afterSale?`申请 ${state.afterSale} 当前为「待审核」，尚未发起退款。退回商品验收通过后才会发起退款，演示到账时间为 1–3 个工作日。`:'暂未创建售后申请。提交申请并完成审核、退货验收后才会发起退款。您可以先查看退货退款方案。'});addEvent('核查售后阶段：'+(state.afterSale?'待审核':'未申请'));}
 else{state.messages.push({role:'ai',text:'已查询到您的订单，以下是商品与售后状态。',card:'order'});if(/退货|退款|售后|坏|破损/.test(text)){state.messages.push({role:'ai',text:'根据商品质量问题退货政策，可以为您申请退货退款，退货运费由商家承担。请核对方案后确认。',card:'scheme'});state.core='收到的保温杯杯盖破损，申请退货退款。';}addEvent('订单查询成功 · 引用政策 KB-2026-018');}
 }else{state.messages.push({role:'ai',text:'当前知识范围内没有足够可靠的信息回答这个问题。我会保留您的问题，转人工继续核实。'});handoff('AI 无法可靠回答 · 知识范围外');return;}
 render();scrollMessages();
}
function openSale(manual=false){if(state.afterSale){toast('该订单已有售后申请，已为您打开现有工单');ticketDetail(state.afterSale);return;}if(manual&&(!state.accepted||state.closed)){toast('请先在林晓的会话中接入服务，再创建售后');state.view='desk';state.selected=1;state.chatOpen=true;render();return;}if(!manual&&(state.transferred||state.closed)){toast('当前会话已转人工，请由客服核实并提交售后');return;}if(state.apiFail){toast('订单接口异常，无法校验售后条件。请重试或转人工。');return;}
 modal(manual?'创建售后工单':'确认售后方案',`<div class="info-banner">林晓 · RL202610220831<br>轻行 · 真空保温杯 / 苔原绿 / 480mL</div><label>售后类型</label><label class="radio-card"><input type="radio" checked name="sale-type"><span><strong>退货退款 · ¥ 129.00</strong>质量问题 · 退货运费由商家承担</span></label><label for="sale-reason">申请原因</label><select id="sale-reason"><option>商品破损 / 杯盖破损</option><option>商品功能异常</option></select><p>提交后进入售后审核。审核通过后再安排退货，退款在商品退回并验收后发起。</p>${manual?'<label class="radio-card"><input type="checkbox" id="manual-consent"><span>已在当前会话中获得客户售后申请授权</span></label>':'<p>点击确认即表示您同意按以上方案发起售后申请。</p>'}<p class="muted">演示操作，不会创建真实工单或执行退款。</p>`,`<button data-action="modal-close">取消</button><button class="primary" data-action="sale-confirm" data-manual="${manual}">确认提交申请</button>`);
}
function confirmSale(manual){if(state.afterSale){closeModal();toast('重复请求已拦截，复用现有工单');return;}if(manual&&!$('#manual-consent')?.checked){toast('请先确认已获得客户授权');return;}if(state.apiFail){toast('订单校验不可用，申请未提交。请恢复接口后重试。');return;}const id='AS202610240001';state.afterSale=id;state.tickets.push({id,reason:$('#sale-reason').value,source:manual?'人工工作台':'客户自助确认',time:new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})});state.messages.push({role:manual?'staff':'ai',text:`退货退款申请已提交，工单号 ${id}，申请金额 ¥129.00，当前待审核。退货运费由商家承担，退款尚未执行。`,card:'receipt'});addEvent('售后申请创建成功 · '+id);closeModal();render();scrollMessages();toast('售后工单已创建，已关联订单与会话');}
function ticketDetail(id){const t=state.tickets.find(t=>t.id===id);if(!t)return;modal('售后工单详情',`<span class="tag orange">待审核 · 未执行退款</span><dl class="keyval"><dt>工单编号</dt><dd>${esc(t.id)}</dd><dt>客户</dt><dd>林晓 · 138 **** 6028</dd><dt>关联订单</dt><dd>RL202610220831</dd><dt>申请金额</dt><dd>¥ 129.00</dd><dt>原因</dt><dd>${esc(t.reason)}</dd><dt>创建来源</dt><dd>${esc(t.source)}</dd><dt>创建时间</dt><dd>${esc(t.time)}</dd></dl><div class="info-banner">已提交 → 待审核 → 待退货 → 验收 → 退款<br>本原型演示至「待审核」，后续资金动作未执行。</div>`,`<button class="primary" data-action="modal-close">知道了</button>`);}
function article(id){const a=articles.find(a=>a.id===id);if(!a)return;modal('知识引用 · 来源溯源',`<span class="tag green">有效政策 · 演示文档</span><h2 style="margin-top:15px">${a.title}</h2><p>${a.version} · 售后服务组</p><div class="info-banner">引用位置：第 2 条 / 服务规则</div><p>${a.body}</p><label>适用范围</label><p>${a.scope}</p><p class="muted">文档内容为原型示例，真实政策以企业已审批版本为准。</p>`,`<button data-action="modal-close">关闭</button><button class="primary" data-action="insert-policy" data-id="${id}">插入客服草稿</button>`);}
function components(){const labels=['快捷意图入口','客户文本消息','AI 身份与状态','输入与发送栏','订单查询结果卡','售后方案卡','来源引用卡','引用原文弹窗','点赞反馈','点踩反馈','售后方案确认弹窗','申请提交回执','物流状态提示','接口异常卡','失败重试按钮','主动转人工入口','人工排队状态','人工接入提示','人工回复消息','会话结束状态','隐私与 AI 提示'];modal('21 个 C 端核心交互组件',`<p>按当前需求拆出的组件清单；订单、方案、引用为三大核心卡片。全部组件可通过正常售后、人工接入、接口失败及结束会话场景查看。</p><div class="component-list">${labels.map((t,i)=>`<div><small>COMPONENT ${String(i+1).padStart(2,'0')}</small>${t}</div>`).join('')}</div>`,`<button class="primary" data-action="modal-close">知道了</button>`,true);}
function guide(){modal('演示指南 · 一次完整的人机协同',`<p>所有客户、订单、知识与回复均为模拟数据。演示状态保存在当前浏览器，切换双端可继续同一段对话。</p><div class="rule-row"><strong>① 先体验一次人工接管</strong><p>默认打开「林晓」高风险投诉。查看 AI 四字段摘要，点击「接入会话」，系统自动发送已阅读历史的接入话术。</p></div><div class="rule-row"><strong>② 让 Copilot 帮忙，人工保留控制权</strong><p>点击「采用并编辑」，修改草稿后发送；在右侧创建售后，确认客户授权，工单同步到客户端及工单页。</p></div><div class="rule-row"><strong>③ 从客户自助重新走一遍</strong><p>进入 C 端，点击「从 AI 售后开始」。查询订单、查看引用，确认售后申请；输入「我要投诉」体验跨端转交。</p></div><div class="rule-row"><strong>④ 验证失败路径与权限</strong><p>C 端模拟接口异常后点击「查订单」，可重试或转人工。工作台切换普通客服将无法接入高风险会话。「标记摘要有误」可提交纠错。</p></div><div class="info-banner">原型不调用真实模型、企业系统或支付服务。「项目成效」页的数字来自需求材料，并非运行统计。</div>`,`<button data-action="components">21 个组件</button><button class="primary" data-action="modal-close">开始体验</button>`);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;
 switch(a){
 case 'nav':state.view=b.dataset.view;state.query='';render();break;
 case 'tab':state.tab=b.dataset.tab;state.query='';render();break;
 case 'session':state.selected=Number(b.dataset.id);state.chatOpen=true;state.draft='';render();break;
 case 'queue-back':state.chatOpen=false;render();break;
 case 'context':state.context=b.dataset.value;render();break;
 case 'guide':guide();break;
 case 'components':components();break;
 case 'modal-close':closeModal();break;
 case 'reset':modal('重置演示数据',`<p>清空本原型保存的消息、工单与反馈，恢复到高风险投诉等待接入的初始场景。</p>`,`<button data-action="modal-close">取消</button><button class="primary" data-action="reset-confirm">重置演示</button>`);break;
 case 'reset-confirm':state=fresh();closeModal();render();toast('已恢复初始演示场景');break;
 case 'new-scenario':modal('从 AI 自助售后开始',`<p>将清空当前演示消息与工单，打开人工介入前的自助售后场景。</p>`,`<button data-action="modal-close">取消</button><button class="primary" data-action="new-confirm">开始自助场景</button>`);break;
 case 'new-confirm':{const fail=state.apiFail;state=fresh();state.view='customer';state.apiFail=fail;state.messages=state.messages.slice(0,3);state.transferred=false;state.accepted=false;state.core='商品杯盖破损，希望申请退货退款。';state.events=state.events.slice(0,2);state.events.push('已展示售后方案，等待客户确认');closeModal();render();break;}
 case 'accept':if(state.selected!==1)return;if(state.role!=='senior'&&selected().risk===2){toast('该会话为高风险投诉，仅高级客服可接入');return;}if(state.accepted||state.closed)return;state.accepted=true;state.tab='active';state.messages.push({role:'staff',text:`林女士您好，我是${state.role==='senior'?'高级客服':'客服'}叶青，已看到您的历史记录和杯盖破损情况，您无需再重复描述。我来继续跟进退货运费与退款申请。`});addEvent('客服叶青已接入 · AI 停止自动发送');render();scrollMessages();toast('接入成功，默认接入话术已同步客户端');break;
 case 'adopt':state.draft=draftText();render();$('#staff-input')?.focus();toast('已放入草稿，可编辑后发送');break;
 case 'regenerate':state.draftIndex++;render();toast('已切换另一条回复建议（规则模拟）');break;
 case 'close-session':modal('完成本次会话',`<p>确认客户问题已得到处理后，结束本次会话。若已有售后工单，工单仍保留当前审核状态。</p>`,`<button data-action="modal-close">继续处理</button><button class="primary" data-action="close-confirm">确认结束</button>`);break;
 case 'close-confirm':state.closed=true;state.tab='done';state.messages.push({role:'system',text:'本次会话已结束，售后工单进度将继续保留。感谢您的信任。'});addEvent('人工确认完成 · 会话已结束');closeModal();render();scrollMessages();break;
 case 'summary-error':modal('标记 AI 摘要有误',`<label for="error-field">存在问题的字段</label><select id="error-field"><option>核心诉求</option><option>已执行动作</option><option>当前状态</option><option>转人工原因</option></select><label for="error-note">纠错说明（必填）</label><textarea id="error-note" placeholder="例如：尚未创建工单，不应写成已完成退款。"></textarea><p>反馈仅用于本地演示，不会自动改写原始聊天记录。</p>`,`<button data-action="modal-close">取消</button><button class="primary" data-action="error-submit">提交纠错</button>`);break;
 case 'error-submit':if(!$('#error-note').value.trim()){toast('请填写纠错说明');$('#error-note').focus();return;}state.summaryError={field:$('#error-field').value,note:$('#error-note').value.trim()};closeModal();render();toast('纠错已记录，原摘要保留以便核查');break;
 case 'article':article(Number(b.dataset.id));break;
 case 'insert-policy':{const ar=articles.find(x=>x.id===Number(b.dataset.id));if(!state.accepted||state.closed){toast('请先接入人工会话，再插入客服草稿');return;}state.draft=ar.body;state.view='desk';state.selected=1;closeModal();render();$('#staff-input')?.focus();toast('引用内容已插入回复草稿');break;}
 case 'ticket-form':openSale(true);break;
 case 'sale-plan':openSale(false);break;
 case 'sale-confirm':confirmSale(b.dataset.manual==='true');break;
 case 'ticket-detail':ticketDetail(b.dataset.id);break;
 case 'history-detail':modal('历史会话 · 2026-10-20',`<p><b>林晓：</b>保温杯是什么材质，容量多大？</p><p><b>AI 助手：</b>杯体为不锈钢材质，容量 480mL。详细信息可查看商品说明。</p><p><b>林晓：</b>了解了，谢谢。</p><div class="info-banner">历史状态：已解决 · 商品咨询<br>模拟历史记录，客户联系方式已脱敏。</div>`);break;
 case 'handoff':handoff(b.dataset.reason||'用户主动要求人工服务');break;
 case 'open-staff':state.view='desk';state.selected=1;state.tab=state.closed?'done':state.accepted?'active':state.transferred?'pending':'ai';state.chatOpen=true;render();scrollMessages();break;
 case 'quick':customerSend(b.dataset.text);break;
 case 'retry-api':state.apiFail=false;if(state.transferred){render();toast('接口已恢复，当前会话由人工继续处理');}else customerSend('查询我的订单');break;
 case 'feedback':state.feedback=b.dataset.value;persist();render();toast(state.feedback==='up'?'感谢反馈，已记录为有帮助':'已记录改进反馈，可转人工继续核实');break;
 case 'api-contract':modal('转人工 · API 数据契约示例',`<p>POST /api/conversations/:id/handoff<br>头部：Authorization、Idempotency-Key；后端校验租户与会话归属。</p><pre>${esc(JSON.stringify({conversation_id:'CS-20261024-001',risk_level:'high',routing:{required_role:'senior',order_by:['risk_desc','wait_desc']},summary:{core_request:state.core,executed_actions:state.afterSale?['查询订单','检索政策','创建售后申请 '+state.afterSale]:['查询订单','检索政策','展示方案（未提交）'],current_status:state.accepted?'human_active':'waiting_human',handoff_reason:state.transferReason},transcript_ref:'完整历史消息引用（服务端授权访问）',order_id:'RL202610220831'},null,2))}</pre><p>成功：200 + handoff_id；冲突：409（已接管）；无权限：403；超时：504（查询状态后再重试）。生产后端需持久化状态、记录审计并保证 AI 与人工不会同时执行。</p>`,`<button data-action="modal-close">关闭</button>`,true);break;
 }
});
document.addEventListener('submit',e=>{if(e.target.id==='customer-form'){e.preventDefault();const text=$('#customer-input').value;customerSend(text);}if(e.target.id==='staff-form'){e.preventDefault();if(!state.accepted||state.closed)return;const text=$('#staff-input').value.trim();if(!text){toast('请先输入回复内容');return;}state.messages.push({role:'staff',text});state.draft='';addEvent('人工回复已发送并同步客户端');render();scrollMessages();toast('回复已发送');}});
document.addEventListener('input',e=>{if(e.target.id==='queue-search'){state.query=e.target.value;$('#queue-items').innerHTML=renderQueue();}if(e.target.id==='staff-input'){state.draft=e.target.value;persist();}});
document.addEventListener('change',e=>{if(e.target.id==='role-select'){state.role=e.target.value;render();toast(state.role==='senior'?'已切换为高级客服':'已切换为普通客服，无法新接入高风险会话');}if(e.target.id==='api-select'){state.apiFail=e.target.value==='fail';render();toast(state.apiFail?'订单接口异常模式已开启，点击「查订单」体验':'订单接口已恢复为正常模式');}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('.modal')){closeModal();return;}if(e.key==='Tab'&&$('.modal')){const items=[...$('.modal').querySelectorAll('button,input,select,textarea,[tabindex="0"]')].filter(el=>!el.disabled);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}if(e.target.id==='staff-input'&&e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();$('#staff-form').requestSubmit();}});
window.addEventListener('storage',e=>{if(e.key!==key||!e.newValue)return;try{const next=JSON.parse(e.newValue);next.view=state.view;state=next;render();}catch{}});
render();
